export default function SocialIcons() {
  const pathname = usePathname();
  const dashPage = pathname?.startsWith("/dashboard");

  return (
    <div
      className={`flex flex-wrap items-center justify-center gap-3 ${!dashPage ? "sm:gap-6 text-foreground" : "text-white"}`}
    >
      {socialLinks.map((link, index) => (
        <Link
          key={index}
          href={link.url}
          target="_blank"
          rel="noopener noreferrer"
        >
          <Tooltip>
            <TooltipTrigger className="size-5 opacity-40 hover:opacity-100 transition-all duration-300">
              {link.icon}
            </TooltipTrigger>
            <TooltipContent className="text-xs font-medium">
              <p>{link.description}</p>
            </TooltipContent>
          </Tooltip>
        </Link>
      ))}
    </div>
  );
}
